    id: "filter/flipMirror",
    program: "flipMirror",
    from: "/*\n * Flip/Mirror effect\n * Apply horizontal/vertical flipping and various mirroring modes\n */\n\n#ifdef GL_ES\nprecision highp float;\n#endif\n\nuniform vec2 tileOffset;\nuniform vec2 fullResolution;\nuniform sampler2D inputTex;\nuniform int flipMode;\n\nout vec4 fragColor;\n\nvoid main() {\n    ivec2 texSize = textureSize(inputTex, 0);\n    vec2 globalCoord = gl_FragCoord.xy + tileOffset;\n    vec2 globalUV = globalCoord / fullResolution;\n\n    vec2 warpedUV = globalUV;\n\n    if (flipMode == 1) {\n        // flip both\n        warpedUV.x = 1.0 - warpedUV.x;\n        warpedUV.y = 1.0 - warpedUV.y;\n    } else if (flipMode == 2) {\n        // flip horizontal\n        warpedUV.x = 1.0 - warpedUV.x;\n    } else if (flipMode == 3) {\n        // flip vertical\n        warpedUV.y = 1.0 - warpedUV.y;\n    } else if (flipMode == 11) {\n        // mirror left to right\n        if (warpedUV.x > 0.5) {\n            warpedUV.x = 1.0 - warpedUV.x;\n        }\n    } else if (flipMode == 12) {\n        // mirror right to left\n        if (warpedUV.x < 0.5) {\n            warpedUV.x = 1.0 - warpedUV.x;\n        }\n    } else if (flipMode == 13) {\n        // mirror up to down\n        if (warpedUV.y > 0.5) {\n            warpedUV.y = 1.0 - warpedUV.y;\n        }\n    } else if (flipMode == 14) {\n        // mirror down to up\n        if (warpedUV.y < 0.5) {\n            warpedUV.y = 1.0 - warpedUV.y;\n        }\n    } else if (flipMode == 15) {\n        // mirror left to right, up to down\n        if (warpedUV.x > 0.5) {\n            warpedUV.x = 1.0 - warpedUV.x;\n        }\n        if (warpedUV.y > 0.5) {\n            warpedUV.y = 1.0 - warpedUV.y;\n        }\n    } else if (flipMode == 16) {\n        // mirror left to right, down to up\n        if (warpedUV.x > 0.5) {\n            warpedUV.x = 1.0 - warpedUV.x;\n        }\n        if (warpedUV.y < 0.5) {\n            warpedUV.y = 1.0 - warpedUV.y;\n        }\n    } else if (flipMode == 17) {\n        // mirror right to left, up to down\n        if (warpedUV.x < 0.5) {\n            warpedUV.x = 1.0 - warpedUV.x;\n        }\n        if (warpedUV.y > 0.5) {\n            warpedUV.y = 1.0 - warpedUV.y;\n        }\n    } else if (flipMode == 18) {\n        // mirror right to left, down to up\n        if (warpedUV.x < 0.5) {\n            warpedUV.x = 1.0 - warpedUV.x;\n        }\n        if (warpedUV.y < 0.5) {\n            warpedUV.y = 1.0 - warpedUV.y;\n        }\n    }\n\n    vec2 localUV = fract((warpedUV * fullResolution - tileOffset) / vec2(texSize));\n    fragColor = texture(inputTex, localUV);\n}",
    to: "/*\n * Flip/Mirror effect\n * Apply horizontal/vertical flipping and various mirroring modes\n */\n\n#ifdef GL_ES\nprecision highp float;\n#endif\n\nuniform vec2 tileOffset;\nuniform vec2 fullResolution;\nuniform sampler2D inputTex;\nuniform int flipMode;\n\nout vec4 fragColor;\n\nvoid main() {\n    ivec2 texSize = textureSize(inputTex, 0);\n    vec2 globalCoord = gl_FragCoord.xy + tileOffset;\n    vec2 globalUV = globalCoord / fullResolution;\n\n    vec2 warpedUV = globalUV;\n\n    if (flipMode == 1) {\n        // flip both\n        warpedUV.x = 1.0 - warpedUV.x;\n        warpedUV.y = 1.0 - warpedUV.y;\n    } else if (flipMode == 2) {\n        // flip horizontal\n        warpedUV.x = 1.0 - warpedUV.x;\n    } else if (flipMode == 3) {\n        // flip vertical\n        warpedUV.y = 1.0 - warpedUV.y;\n    } else if (flipMode == 11) {\n        // mirror left to right\n        if (warpedUV.x > 0.5) {\n            warpedUV.x = 1.0 - warpedUV.x;\n        }\n    } else if (flipMode == 12) {\n        // mirror right to left\n        if (warpedUV.x < 0.5) {\n            warpedUV.x = 1.0 - warpedUV.x;\n        }\n    } else if (flipMode == 13) {\n        // mirror up to down. warpedUV.y runs up the frame, so the top half\n        // is warpedUV.y > 0.5 and the bottom half samples its reflection.\n        if (warpedUV.y < 0.5) {\n            warpedUV.y = 1.0 - warpedUV.y;\n        }\n    } else if (flipMode == 14) {\n        // mirror down to up\n        if (warpedUV.y > 0.5) {\n            warpedUV.y = 1.0 - warpedUV.y;\n        }\n    } else if (flipMode == 15) {\n        // mirror left to right, up to down\n        if (warpedUV.x > 0.5) {\n            warpedUV.x = 1.0 - warpedUV.x;\n        }\n        if (warpedUV.y < 0.5) {\n            warpedUV.y = 1.0 - warpedUV.y;\n        }\n    } else if (flipMode == 16) {\n        // mirror left to right, down to up\n        if (warpedUV.x > 0.5) {\n            warpedUV.x = 1.0 - warpedUV.x;\n        }\n        if (warpedUV.y > 0.5) {\n            warpedUV.y = 1.0 - warpedUV.y;\n        }\n    } else if (flipMode == 17) {\n        // mirror right to left, up to down\n        if (warpedUV.x < 0.5) {\n            warpedUV.x = 1.0 - warpedUV.x;\n        }\n        if (warpedUV.y < 0.5) {\n            warpedUV.y = 1.0 - warpedUV.y;\n        }\n    } else if (flipMode == 18) {\n        // mirror right to left, down to up\n        if (warpedUV.x < 0.5) {\n            warpedUV.x = 1.0 - warpedUV.x;\n        }\n        if (warpedUV.y > 0.5) {\n            warpedUV.y = 1.0 - warpedUV.y;\n        }\n    }\n\n    vec2 localUV = fract((warpedUV * fullResolution - tileOffset) / vec2(texSize));\n    fragColor = texture(inputTex, localUV);\n}"
