// Apply every patch registered for `id` to a freshly loaded mini-bundle instance.
// Mutates instance.shaders[program].glsl in place, before registerEffect runs.
export function applyUpstreamShaderPatches (id, instance) {
  for (const patch of PATCHES) {
    if (patch.id !== id) continue
    const shader = instance.shaders && instance.shaders[patch.program]
    if (!shader || typeof shader.glsl !== 'string') {
      throw new Error(`upstream shader patch ${id}/${patch.program}: program missing from the loaded mini-bundle`)
    }
    if (shader.glsl === patch.to) continue // already carries the upstream GLSL
    if (shader.glsl !== patch.from) {
      throw new Error(`upstream shader patch ${id}/${patch.program}: vendored GLSL matches neither the pinned revision nor the patched target — refresh this file against vendor/fetch.sh's engine`)
    }
    shader.glsl = patch.to
  }
}
